'use strict';
// The book club and its books in Spanish (D1; club.js is the engine, READ.md the books' authoring guide).
// Latin American (Mexican) Spanish, written natively at each band; never genders the player; PG; original characters; folk tales
// retold in our own words, each opening with a line that credits its tradition.
// The authoring shape (every language follows it):
//   CLUB.add(lang, { name, members: { id: { name, role, look (TALKUI.face), rig (ZHF.person), book (color), pitch, rate } } × 2,
//     host: { pitch, rate } (the librarian's voice), tf: [[true, en], [false, en], [not said, en]],
//     lines: { open ({title}), right, wrong, thanks ({title}) } (the meeting: [text, en] each),
//     lib: { intro, board, cat } (the librarian's own lines in the world, { text, en }: joined to his lines as club_*),
//     notice: { head, pick ('{band}' and '{title}'), meet, none } (the notice board), cat: { name, head, notice: [[text, en] …],
//     where_en, to_en, found_en } (the lost cat's notice on the library's door) })
//   READ.add(lang, { books }) with, on each club book, club: { items: [3–4 items, as in quiz.js], opinion: { ask, want (TALK's),
//     starter, model, simple }, takes: { member: [text, en] } }

